{
  "root": "main",
  "state": {
    "allocation": [
      { "category": "Income", "amount": "$5,400", "notes": "Net take-home" },
      { "category": "Rent", "amount": "$1,650", "notes": "Fixed" },
      { "category": "Utilities", "amount": "$180", "notes": "Fixed" },
      { "category": "Transit", "amount": "$120", "notes": "Fixed" },
      { "category": "Groceries", "amount": "$450", "notes": "Fixed" },
      { "category": "Phone", "amount": "$55", "notes": "Fixed" },
      { "category": "Subscriptions", "amount": "$42", "notes": "Trim if needed" },
      { "category": "Min. debt payments", "amount": "$275", "notes": "CC A $95 + CC B $35 + Student loan $145" },
      { "category": "Emergency fund", "amount": "$600", "notes": "Build toward 3 months" },
      { "category": "High-interest debt extra", "amount": "$1,300", "notes": "Focus on CC A first" },
      { "category": "Vacation fund", "amount": "$400", "notes": "Reach $2,000 in 5 months" },
      { "category": "Remaining cushion", "amount": "$328", "notes": "Buffer / irregular expenses" }
    ],
    "timeline": [
      { "range": "Months 1-3", "focus": "Kill CC A", "happens": "Pay minimums on all debts; send extra to CC A" },
      { "range": "Months 4-5", "focus": "Kill CC B", "happens": "Redirect CC A payment to CC B" },
      { "range": "Months 1-7", "focus": "Build emergency fund", "happens": "Add $600/month until target is reached" },
      { "range": "Months 1-5", "focus": "Fund vacation", "happens": "Add $400/month until $2,000 is reached" },
      { "range": "Months 6-12", "focus": "Attack student loan", "happens": "Use freed-up card payments to accelerate loan payoff" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "allocationTable", "timelineTable", "actions"]
    },
    "title": {
      "type": "Text",
      "props": { "text": "Personal Budget Snapshot and Payoff Plan", "variant": "h1" },
      "children": []
    },
    "allocationTable": {
      "type": "Table",
      "props": {
        "title": "Monthly Allocation",
        "columns": [
          { "key": "category", "label": "Category" },
          { "key": "amount", "label": "Amount" },
          { "key": "notes", "label": "Notes" }
        ],
        "statePath": "/allocation",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "timelineTable": {
      "type": "Table",
      "props": {
        "title": "12-Month Execution Timeline",
        "columns": [
          { "key": "range", "label": "Month Range" },
          { "key": "focus", "label": "Main Focus" },
          { "key": "happens", "label": "What Happens" }
        ],
        "statePath": "/timeline",
        "domain": "schedule",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": {
      "type": "Button",
      "props": { "label": "Budget Planner", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.nerdwallet.com/article/finance/budget-worksheet" } } } },
      "children": []
    },
    "btn2": {
      "type": "Button",
      "props": { "label": "Debt Avalanche", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.consumerfinance.gov/consumer-tools/debt-collection/" } } } },
      "children": []
    },
    "btn3": {
      "type": "Button",
      "props": { "label": "Emergency Fund Guide", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.consumerfinance.gov/consumer-tools/savings/" } } } },
      "children": []
    }
  }
}
